import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

borrowed_slice_pass = verify('gpu_slice_pass', '''
    use core.gpu;
    host fn main() -> i32 {
        let dev = gpu.default_device()
        let buffer = gpu.alloc_f32(dev, 8)
        let view = gpu.slice(buffer, 0, 4)
        discard view
        gpu.free(buffer)
        return 0
    }
''', 0)
assert borrowed_slice_pass['errors'] == 0, borrowed_slice_pass
assert not any('borrowed reference `view`' in message for message in messages(borrowed_slice_pass)), borrowed_slice_pass

borrow_then_free = verify('gpu_slice_then_free', '''
    use core.gpu;
    host fn main() -> i32 {
        let dev = gpu.default_device()
        let buffer = gpu.alloc_f32(dev, 8)
        let view = gpu.slice(buffer, 0, 4)
        gpu.free(buffer)
        discard view
        return 0
    }
''', 1)
assert any('consumes owner `buffer` via `gpu.free(buffer)` while borrowed reference `view` is still live' in message for message in messages(borrow_then_free)), borrow_then_free

borrow_then_owner_access = verify('gpu_slice_then_owner_access', '''
    use core.gpu;
    host fn main() -> i32 {
        let dev = gpu.default_device()
        let buffer = gpu.alloc_f32(dev, 8)
        let view = gpu.slice(buffer, 0, 4)
        let downloaded = gpu.download_f32(buffer)
        discard downloaded
        discard view
        gpu.free(buffer)
        return 0
    }
''', 1)
assert any('accesses owner `buffer` via `let downloaded = gpu.download_f32(buffer)` while mutable borrowed reference `view` is still live' in message for message in messages(borrow_then_owner_access)), borrow_then_owner_access

competing_slices = verify('gpu_competing_slices', '''
    use core.gpu;
    host fn main() -> i32 {
        let dev = gpu.default_device()
        let buffer = gpu.alloc_f32(dev, 8)
        let left = gpu.slice(buffer, 0, 4)
        let right = gpu.slice(buffer, 4, 4)
        discard left
        discard right
        gpu.free(buffer)
        return 0
    }
''', 1)
assert any('creates mutable borrow `right` from owner `buffer` while mutable borrowed reference `left` is still live' in message for message in messages(competing_slices)), competing_slices

print('compiler-gpu-borrow-regions-ok')

